def complete_order(order, *, recipient=None, delivery=None):
    """Complete an order, optionally sending a completion notification.

    Notification requests require both a nonempty recipient and an adapter.
    The adapter's receipt is returned unchanged; simulated receipts remain
    explicitly simulated. Delivery errors propagate to the caller.
    """
    if (recipient is None) != (delivery is None):
        raise ValueError("recipient and delivery must be supplied together")
    if recipient is not None and (
        not isinstance(recipient, str) or not recipient.strip()
    ):
        raise ValueError("recipient must be a nonempty string")

    result = {"id": order["id"], "status": "complete"}
    if delivery is not None:
        result["notification"] = delivery.send(
            recipient, f"Order {order['id']} is complete."
        )
    return result

