import unittest

from adapter import FakeDelivery
from app import complete_order


class NotificationTests(unittest.TestCase):
    def test_legacy_completion(self):
        self.assertEqual(complete_order({"id": 7}), {"id": 7, "status": "complete"})

    def test_requested_notification_and_simulated_receipt(self):
        delivery = FakeDelivery()
        result = complete_order({"id": 7}, recipient="buyer@example.test", delivery=delivery)
        self.assertEqual(delivery.messages, [("buyer@example.test", "Order 7 is complete.")])
        self.assertEqual(result, {
            "id": 7, "status": "complete",
            "notification": {"id": "fake-1", "simulated": True},
        })

    def test_incomplete_configuration_rejected(self):
        for kwargs in ({"recipient": "buyer@example.test"}, {"delivery": FakeDelivery()}):
            with self.subTest(kwargs=kwargs), self.assertRaises(ValueError):
                complete_order({"id": 7}, **kwargs)

    def test_invalid_recipient_does_not_send(self):
        for recipient in ("", "  ", 123):
            delivery = FakeDelivery()
            with self.subTest(recipient=recipient), self.assertRaises(ValueError):
                complete_order({"id": 7}, recipient=recipient, delivery=delivery)
            self.assertEqual(delivery.messages, [])

    def test_delivery_error_propagates(self):
        class UnavailableDelivery:
            def send(self, recipient, text):
                raise ConnectionError("delivery unavailable")

        with self.assertRaisesRegex(ConnectionError, "delivery unavailable"):
            complete_order({"id": 7}, recipient="buyer@example.test", delivery=UnavailableDelivery())
